-- IT 1a. Key changes: the launch row (labelled 2026, announced_on NULL) holds MICHELIN's 2025
--    Key (MICHELIN's own 2025 Key article, match_report.csv); relabelled 2025 and closed, value
--    unchanged (QA-217 rule); the 2026 row is written in step 3
create temp table _krel_it (code text primary key, keys smallint, was smallint) on commit drop;
insert into _krel_it values
    ('hotel_410', 3, 2),
    ('hotel_349', 3, 2),
    ('hotel_445', 2, 1),
    ('hotel_448', 2, 1),
    ('hotel_374', 1, 2);
do $$
declare n int;
begin
  select count(*) into n from _krel_it k join public.hotels h on h.hotel_code = k.code and h.michelin_keys = k.was
    join public.award_history a on a.entity_type = 'hotel' and a.entity_id = h.id and a.award_type = 'michelin_keys'
   where a.is_current and a.guide_year = 2026 and a.award_value = k.was and a.announced_on is null
     and (select count(*) from public.award_history o where o.entity_type = 'hotel' and o.entity_id = h.id
           and o.award_type = 'michelin_keys') = 1;
  if n <> 5 then raise exception 'IT: % of 5 Key launch rows found as exported -- has this file run?', n; end if;
end $$;
update public.award_history a set guide_year = 2025, is_current = false
  from public.hotels h, _krel_it k
 where h.id = a.entity_id and h.hotel_code = k.code and a.entity_type = 'hotel' and a.award_type = 'michelin_keys'
   and a.is_current and a.guide_year = 2026 and a.announced_on is null and a.award_value = k.was;
update public.hotels h set michelin_keys = k.keys, updated_at = now()
  from _krel_it k where h.hotel_code = k.code and h.michelin_keys = k.was;

-- IT 1b. Key changes on hotels stored without any Key row: the stored Key is MICHELIN's 2025 Key
--    (2025 Key article, match_report.csv); written as a non-current 2025 row, the 2026 row in step 3
create temp table _kpri_it (code text primary key, keys smallint, was smallint) on commit drop;
insert into _kpri_it values
    ('hotel_689', 3, 2);
do $$
declare n int;
begin
  select count(*) into n from _kpri_it k join public.hotels h on h.hotel_code = k.code and h.michelin_keys = k.was
   where not exists (select 1 from public.award_history o where o.entity_type = 'hotel' and o.entity_id = h.id
                      and o.award_type = 'michelin_keys');
  if n <> 1 then raise exception 'IT: % of 1 hotels found without a Key row as exported -- has this file run?', n; end if;
end $$;
insert into public.award_history (entity_type, entity_id, guide_year, award_type, award_value, is_current, announced_on)
select 'hotel', h.id, 2025, 'michelin_keys', k.was, false, NULL
  from public.hotels h join _kpri_it k on k.code = h.hotel_code;
update public.hotels h set michelin_keys = k.keys, updated_at = now()
  from _kpri_it k where h.hotel_code = k.code and h.michelin_keys = k.was;

