do $$
declare bad text;
begin
  if exists (select 1 from public.hotels h join _new_it x on x.code = h.hotel_code) then
    raise exception 'IT: hotel codes hotel_2701..hotel_2770 are no longer free -- re-check';
  end if;
  select string_agg(x.name || ' (' || x.city || ')', ', ') into bad from _new_it x
   where (select count(*) from public.cities c where c.country_code = 'IT' and c.name = x.city) <> 1;
  if bad is not null then raise exception 'IT: hotel city does not resolve to exactly one row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_it x join public.hotels h
    on substring(h.michelin_url from '-([0-9]+)/?$') = substring(x.michelin_url from '-([0-9]+)/?$');
  if bad is not null then raise exception 'IT: hotel already present (MICHELIN id): %', bad; end if;
end $$;
insert into public.hotels (hotel_code, name, michelin_keys, city_id, country_code, address, location, michelin_url)
select x.code, x.name, x.keys,
       (select c.id from public.cities c where c.country_code = 'IT' and c.name = x.city), 'IT',
       x.address, ST_SetSRID(ST_MakePoint(x.lon, x.lat), 4326)::geography, x.michelin_url
  from _new_it x;

-- IT 3. current 2026 Key row for the Key changes, the new hotels and the existing hotels
--    imported without any Key row
insert into public.award_history (entity_type, entity_id, guide_year, award_type, award_value, is_current, announced_on)
select 'hotel', h.id, 2026, 'michelin_keys', h.michelin_keys, true, date '2026-09-18'
  from public.hotels h
 where h.hotel_code = any(array['hotel_689', 'hotel_410', 'hotel_349', 'hotel_445', 'hotel_448', 'hotel_374', 'hotel_2701', 'hotel_2702', 'hotel_2703', 'hotel_2704', 'hotel_2705', 'hotel_2706', 'hotel_2707', 'hotel_2708', 'hotel_2709', 'hotel_2710', 'hotel_2711', 'hotel_2712', 'hotel_2713', 'hotel_2714', 'hotel_2715', 'hotel_2716', 'hotel_2717', 'hotel_2718', 'hotel_2719', 'hotel_2720', 'hotel_2721', 'hotel_2722', 'hotel_2723', 'hotel_2724', 'hotel_2725', 'hotel_2726', 'hotel_2727', 'hotel_2728', 'hotel_2729', 'hotel_2730', 'hotel_2731', 'hotel_2732', 'hotel_2733', 'hotel_2734', 'hotel_2735', 'hotel_2736', 'hotel_2737', 'hotel_2738', 'hotel_2739', 'hotel_2740', 'hotel_2741', 'hotel_2742', 'hotel_2743', 'hotel_2744', 'hotel_2745', 'hotel_2746', 'hotel_2747', 'hotel_2748', 'hotel_2749', 'hotel_2750', 'hotel_2751', 'hotel_2752', 'hotel_2753', 'hotel_2754', 'hotel_2755', 'hotel_2756', 'hotel_2757', 'hotel_2758', 'hotel_2759', 'hotel_2760', 'hotel_2761', 'hotel_2762', 'hotel_2763', 'hotel_2764', 'hotel_2765', 'hotel_2766', 'hotel_2767', 'hotel_2768', 'hotel_2769', 'hotel_2770', 'hotel_690', 'hotel_691', 'hotel_693', 'hotel_696', 'hotel_694'])
   and not exists (select 1 from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
                    and a.award_type = 'michelin_keys' and a.is_current);

-- IT 4. post-conditions
do $$
declare n int;
begin
  select count(*) into n from public.hotels where country_code = 'IT' and michelin_keys is not null;
  if n <> 224 then raise exception 'IT: expected 224 Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'IT' and michelin_keys = 1;
  if n <> 158 then raise exception 'IT: expected 158 1-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'IT' and michelin_keys = 2;
  if n <> 49 then raise exception 'IT: expected 49 2-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'IT' and michelin_keys = 3;
  if n <> 17 then raise exception 'IT: expected 17 3-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels h where h.country_code = 'IT' and h.michelin_keys is not null
     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and a.is_current and a.award_value = h.michelin_keys) <> 1;
  if n <> 0 then raise exception 'IT: % Key hotels without exactly one matching current Key row', n; end if;
  select count(*) into n from public.hotels h where h.hotel_code = any(array['hotel_389'])
     and h.michelin_keys is null
     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and a.is_current and a.award_value is null and a.guide_year = 2026) = 1
     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and not a.is_current and a.guide_year = 2025) = 1;
  if n <> 1 then raise exception 'IT: % of 1 lost-Key hotels end as expected', n; end if;
end $$;


