-- ES 1a. Key changes: the launch row (labelled 2026, announced_on NULL) holds MICHELIN's 2025
--    Key (MICHELIN's own 2025 Key article, match_report.csv); relabelled 2025 and closed, value
--    unchanged (QA-217 rule); the 2026 row is written in step 3
create temp table _krel_es (code text primary key, keys smallint, was smallint) on commit drop;
insert into _krel_es values
    ('hotel_539', 2, 1),
    ('hotel_525', 2, 1);
do $$
declare n int;
begin
  select count(*) into n from _krel_es k join public.hotels h on h.hotel_code = k.code and h.michelin_keys = k.was
    join public.award_history a on a.entity_type = 'hotel' and a.entity_id = h.id and a.award_type = 'michelin_keys'
   where a.is_current and a.guide_year = 2026 and a.award_value = k.was and a.announced_on is null
     and (select count(*) from public.award_history o where o.entity_type = 'hotel' and o.entity_id = h.id
           and o.award_type = 'michelin_keys') = 1;
  if n <> 2 then raise exception 'ES: % of 2 Key launch rows found as exported -- has this file run?', n; end if;
end $$;
update public.award_history a set guide_year = 2025, is_current = false
  from public.hotels h, _krel_es k
 where h.id = a.entity_id and h.hotel_code = k.code and a.entity_type = 'hotel' and a.award_type = 'michelin_keys'
   and a.is_current and a.guide_year = 2026 and a.announced_on is null and a.award_value = k.was;
update public.hotels h set michelin_keys = k.keys, updated_at = now()
  from _krel_es k where h.hotel_code = k.code and h.michelin_keys = k.was;

-- ES 1c. Key import errors: the launch row's value matches no MICHELIN edition (2024, 2025 and
--    2026 articles and pages agree with each other, not with it); corrected in place to 2026
create temp table _kfix_es (code text primary key, keys smallint, was smallint) on commit drop;
insert into _kfix_es values
    ('hotel_519', 3, 2),
    ('hotel_520', 2, 1),
    ('hotel_506', 2, 1),
    ('hotel_566', 2, 1),
    ('hotel_558', 2, 1);
do $$
declare n int;
begin
  select count(*) into n from _kfix_es k join public.hotels h on h.hotel_code = k.code and h.michelin_keys = k.was
    join public.award_history a on a.entity_type = 'hotel' and a.entity_id = h.id and a.award_type = 'michelin_keys'
   where a.is_current and a.guide_year = 2026 and a.award_value = k.was and a.announced_on is null;
  if n <> 5 then raise exception 'ES: % of 5 Key launch rows found as exported -- has this file run?', n; end if;
end $$;
update public.award_history a set award_value = k.keys
  from public.hotels h, _kfix_es k
 where h.id = a.entity_id and h.hotel_code = k.code and a.entity_type = 'hotel' and a.award_type = 'michelin_keys'
   and a.is_current and a.guide_year = 2026 and a.announced_on is null and a.award_value = k.was;
update public.hotels h set michelin_keys = k.keys, updated_at = now()
  from _kfix_es k where h.hotel_code = k.code and h.michelin_keys = k.was;

