     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and a.is_current and a.award_value = h.michelin_keys) <> 1;
  if n <> 0 then raise exception 'ES: % Key hotels without exactly one matching current Key row', n; end if;
  select count(*) into n from public.hotels h where h.hotel_code = any(array['hotel_463', 'hotel_477', 'hotel_494', 'hotel_551', 'hotel_561'])
     and h.michelin_keys is null
