create temp table _krel_de (code text primary key, keys smallint, was smallint) on commit drop;
insert into _krel_de values
    ('hotel_201', 2, 1),
    ('hotel_182', 2, 1),
    ('hotel_252', 2, 1),
    ('hotel_200', 2, 1),
    ('hotel_202', 2, 1),
    ('hotel_114', 1, 2),
